  `show_val` int NOT NULL DEFAULT '0' COMMENT '曝光值',
  `recommend_val` int NOT NULL DEFAULT '0' COMMENT '推荐值',
  `labelid` int NOT NULL DEFAULT '0' COMMENT '标签ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
