INSERT INTO `cmf_live_class` VALUES (1,'音乐','liveclass_1.png','流行、摇滚、说唱、民族等，线上最强演唱会',2,'Music','Pop, rock, rap, ethnic, etc., the most powerful online concert'),(2,'舞蹈','liveclass_2.png','现代舞、钢管舞、肚皮舞等，谈恋爱不如跳舞',1,'Dance','Modern dance, pole dancing, belly dancing, etc., falling in love is not as good as dancing'),(3,'户外','liveclass_3.png','街头、野外任你选择，健身、旅行任你畅玩',3,'Outdoor','You can choose from the streets or outdoors, and you can enjoy fitness and travel.'),(4,'校园','liveclass_4.png','学生党分享校园乐事',4,'Campus','Student parties share campus fun'),(5,'交友','liveclass_5.png','单身男女聚集地，线上交友趣事多',5,'Make friends','A gathering place for single men and women, with lots of interesting things to do online'),(6,'喊麦','liveclass_6.png','欧美有RAP，我们有MC',6,'Shout out to Mai','Europe and America have RAP, we have MC'),(7,'游戏','liveclass_7.png','是时候展示你真正的技术了',7,'Game','It\'s time to show your real skills'),(8,'直播购','liveclass_8.png','买买买，分享最美好的东西',0,'Live purchase','Buy, buy, buy and share the best things'),(9,'美食','liveclass_9.png','吃货？主厨？唯美食不可辜负',9,'Gourmet food','Foodie? Chef? Food is the only thing you can’t live up to'),(10,'才艺','liveclass_10.png','手工艺、魔术、画画、化妆等，艺术高手在民间',10,'Talent','Handicrafts, magic, painting, makeup, etc., art masters among the people'),(11,'男神','liveclass_11.png','前方有一大波迷妹即将赶到',11,'Male god','There\'s a big wave of fans ahead, and they\'re about to arrive'),(12,'女神','liveclass_12.png','高颜值，好身材就要秀出来',12,'Goddess','Good looks and a good figure should be shown off');
/*!40000 ALTER TABLE `cmf_live_class` ENABLE KEYS */;
