CREATE TABLE `cmf_lottery_game` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_id` int unsigned NOT NULL DEFAULT '0',
  `category_id` int unsigned NOT NULL DEFAULT '0',
  `game_code` varchar(60) NOT NULL DEFAULT '' COMMENT 'local game code',
  `game_name` varchar(100) NOT NULL DEFAULT '',
  `game_name_en` varchar(100) NOT NULL DEFAULT '',
  `source_lottery_id` varchar(60) NOT NULL DEFAULT '' COMMENT 'Boyi lotteryid for newdata',
  `source_e_name` varchar(60) NOT NULL DEFAULT '' COMMENT 'Boyi e_name for history',
  `icon` varchar(255) NOT NULL DEFAULT '',
  `description` text,
  `rule_desc` text,
  `interval_sec` int unsigned NOT NULL DEFAULT '60',
  `seal_advance_sec` int unsigned NOT NULL DEFAULT '5' COMMENT 'seconds before open time to stop betting',
  `min_bet` bigint unsigned NOT NULL DEFAULT '10',
  `max_bet` bigint unsigned NOT NULL DEFAULT '500000',
  `max_issue_bet` bigint unsigned NOT NULL DEFAULT '1000000',
  `sort` int NOT NULL DEFAULT '0',
  `sync_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 stop sync, 1 sync',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 hidden, 1 enabled, 2 maintenance',
  `last_issue_num` varchar(80) NOT NULL DEFAULT '',
  `last_open_code` varchar(100) NOT NULL DEFAULT '',
  `last_open_time` int unsigned NOT NULL DEFAULT '0',
  `create_time` int unsigned NOT NULL DEFAULT '0',
  `update_time` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_game_code` (`game_code`),
  KEY `idx_source_e_name` (`source_id`,`source_e_name`),
  KEY `idx_category_status` (`category_id`,`status`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Lottery game';
