  `issue_num` varchar(80) NOT NULL DEFAULT '',
  `open_code` varchar(100) NOT NULL DEFAULT '',
  `open_time` int unsigned NOT NULL DEFAULT '0',
  `seal_time` int unsigned NOT NULL DEFAULT '0',
  `source_time` varchar(40) NOT NULL DEFAULT '',
  `next_open_time` int unsigned NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 open, 1 sealed, 2 opened, 3 settled, 4 canceled',
  `sync_time` int unsigned NOT NULL DEFAULT '0',
  `settle_time` int unsigned NOT NULL DEFAULT '0',
  `create_time` int unsigned NOT NULL DEFAULT '0',
  `update_time` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_game_issue` (`game_id`,`issue_num`),
  KEY `idx_game_status_time` (`game_id`,`status`,`open_time`),
  KEY `idx_status_open_time` (`status`,`open_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3970 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Lottery issue';
