  `orders_win` int unsigned NOT NULL DEFAULT '0',
  `orders_lose` int unsigned NOT NULL DEFAULT '0',
  `payout_total` bigint unsigned NOT NULL DEFAULT '0',
  `success` tinyint(1) NOT NULL DEFAULT '0',
  `message` varchar(1000) NOT NULL DEFAULT '',
  `create_time` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_issue_key` (`issue_id`,`settle_key`)
) ENGINE=InnoDB AUTO_INCREMENT=3965 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Lottery settle log';
