CREATE TABLE `cmf_lottery_source` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT 'source code',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'source name',
  `base_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'base API url',
  `official_token` varchar(255) NOT NULL DEFAULT '' COMMENT 'official paid API token',
  `aes_key` varchar(100) NOT NULL DEFAULT '' COMMENT 'response AES key',
  `aes_iv` varchar(50) NOT NULL DEFAULT '' COMMENT 'response AES iv',
  `response_encrypt` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 encrypted response',
  `request_encrypt` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 encrypted request',
  `poll_interval` int unsigned NOT NULL DEFAULT '5' COMMENT 'poll interval seconds',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 disabled, 1 enabled',
  `last_sync_time` int unsigned NOT NULL DEFAULT '0',
  `last_error` varchar(500) NOT NULL DEFAULT '',
  `create_time` int unsigned NOT NULL DEFAULT '0',
  `update_time` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Lottery external data source';
