formation.Ifyouagree,pleaseclicktoagreetoacceptourservices.\",\"login_clause_title_en\":\"Ihavereadindetailandagreetothe《PrivacyPolicy》and《ServiceAgreement》\",\"login_private_title_en\":\"PrivacyPolicy\",\"login_service_title_en\":\"ServiceAgreement\",\"teenager_des_en\":\"Inordertoprotectthehealthygrowthofminors,ayouthmodeisspeciallylaunched.Inthismode,somefunctionscannotbeusednormally.Guardiansareaskedtoactivelychooseandsetaguardianshippassword.\"}'),(2,1,'appstore_settings','{\"access_token\":\"5b573b6175811b9c104dfb1557f05ace53b6ff441c5c464022973578d29246c3\"}'),(3,1,'storage','{\"storages\":{\"Qiniu\":{\"name\":\"七牛云存储\",\"driver\":\"\\\\plugins\\\\qiniu\\\\lib\\\\Qiniu\"}},\"type\":\"Qiniu\"}'),(4,1,'upload_setting','{\"max_files\":\"20\",\"chunk_size\":\"512\",\"file_types\":{\"image\":{\"upload_max_filesize\":\"102400\",\"extensions\":\"jpg,jpeg,png,gif,bmp4\"},\"video\":{\"upload_max_filesize\":\"102400\",\"extensions\":\"mp4,avi,wmv,rm,rmvb,mkv\"},\"audio\":{\"upload_max_filesize\":\"102400\",\"extensions\":\"mp3,wma,wav\"},\"file\":{\"upload_max_filesize\":\"102400\",\"extensions\":\"txt,pdf,doc,docx,xls,xlsx,ppt,pptx,zip,rar,mp4,svga\"}}}'),(5,1,'cdn_settings','{\"cdn_static_root\":\"\"}'),(6,1,'admin_settings','{\"admin_password\":\"\",\"admin_theme\":\"admin_simpleboot3\",\"admin_style\":\"flatadmin\"}'),(7,1,'configpri','{\"family_switch\":\"1\",\"family_member_divide_switch\":\"1\",\"service_switch\":\"1\",\"service_url\":\"\",\"list_coin_switch\":\"1\",\"sensitive_words\":\"毛泽东,习近平,胡锦涛,江泽民,朱镕基,且,weixin,qq,微信,QQ,流流\",\"reg_reward\":\"0\",\"bonus_switch\":\"1\",\"login_wx_pc_appid\":\"\",\"login_wx_pc_appsecret\":\"\",\"login_wx_appid\":\"\",\"login_wx_appsecret\":\"\",\"login_qq_appid\":\"\",\"sendcode_switch\":\"0\",\"typecode_switch\":\"1\",\"aly_keyid\":\"\",\"aly_secret\":\"\",\"aly_sendcode_type\":\"3\",\"aly_signName\":\"\",\"aly_templateCode\":\"\",\"aly_hw_signName\":\"\",\"aly_hw_templateCode\":\"\",\"ccp_sid\":\"\",\"ccp_token\":\"\",\"ccp_