DROP TABLE IF EXISTS `cmf_portal_post`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cmf_portal_post` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '发表者用户id',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `post_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'post标题',
  `post_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '文章内容',
  `post_content_filtered` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '处理过的文章内容',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '页面类型，0单页面，2个人中心展示',
  `list_order` int NOT NULL DEFAULT '9999' COMMENT '序号',
  `post_title_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '英文标题',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type_status_date` (`create_time`,`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='portal应用 文章表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `cmf_portal_post` WRITE;
/*!40000 ALTER TABLE `cmf_portal_post` DISABLE KEYS */;
INSERT INTO `cmf_portal_post` VALUES (2,1,1659597034,1698062932,'社区公约','&lt;p&gt;&amp;nbsp; 社区公约，内容可在管理后台设置。1&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p&gt;&lt;br/&gt;&lt;/p&gt;&lt;p&gt;&lt;br/&gt;&lt;/p&gt;',NULL,2,2,'community convention'),(3,1,1659597034,1672305487,'隐私政策','&lt;p&gt;隐私政策，内容可在管理后台设置。&lt;/p&gt;',NULL,2,1,'Privacy Policy'),(4,1,1659597034,0,'服务协议','&lt;p&gt;  服务协议，内容可在管理后台设置。&lt;/p&gt;',NULL,2,3,'Service Agreement'),(5,1,1659597034,0,'联系我们','\n&lt;p style=&quot;margin-top: 0px; margin-bottom: 20px; white-space: normal; padding: 0px; font-size: 14px; line-height: 25.2px; text-indent: 28px; color: rgb(85, 85, 85); font-family: arial, &quot;&gt;联系我们，内容可在管理后台设置。&lt;/p&gt;\n&lt;p&gt;&lt;br&gt;&lt;/p&gt;\n',NULL,2,4,'contact us'),(6,1,1659597034,0,'用户充值协议','&lt;p&gt;用户充值协议用户充值协议用户充值协议用户充值协议&lt;/p&gt;',NULL,0,9999,'User Recharge Agreement'),(10,1,1659597034,1665128630,'主播协议','&lt;p&gt;&amp;nbsp; &amp;nbsp;主播协议，内容可在管理后台设置。&lt;/p&gt;',NULL,2,5,'Anchor Agreement'),(18,1,1659597034,0,'签约说明','&lt;p&gt;签约说明&lt;/p&gt;',NULL,0,9999,'Signing instructions'),(26,1,1659597034,0,'幸运礼物说明','&lt;p&gt;幸运礼物功能，用户送出“幸运礼物”会有几率获得礼物翻倍中奖和奖池中奖的机会。&lt;/p&gt;',NULL,0,9999,'Lucky gift instructions'),(31,1,1659597034,0,'直播带货功能','&lt;p&gt;轮播1&lt;/p&gt;',NULL,0,9999,'Live delivery function'),(33,1,1659597034,0,'直播系统','&lt;p&gt;轮播2&lt;/p&gt;',NULL,0,9999,'Live broadcast system'),(34,1,1659597034,0,'超值服务','&lt;p&gt;轮播3&lt;/p&gt;',NULL,0,9999,'Value service'),(35,1,1659597034,0,'转盘规则','&lt;p&gt;转盘规则转盘规则转盘规则&lt;/p&gt;',NULL,0,9999,'wheel rules'),(38,1,1659597034,0,'小店界面联系客服','&lt;p&gt;小店界面联系客服&lt;/p&gt;',NULL,0,9999,'Contact customer service through store interface'),(39,1,1659597034,0,'道具礼物说明','\n&lt;p style=&quot;white-space: normal;&quot;&gt;道具礼物说明&lt;/p&gt;\n&lt;p style=&quot;white-space: normal;&quot;&gt;道具礼物说明&lt;/p&gt;\n&lt;p style=&quot;white-space: normal;&quot;&gt;道具礼物说明&lt;/p&gt;\n&lt;p&gt;&lt;br&gt;&lt;/p&gt;\n',NULL,0,9999,'Prop gift instructions'),(40,1,1659597034,0,'付费内容管理规范','&lt;p&gt;付费内容管理规范说明&lt;/p&gt;',NULL,0,9999,'Paid content management specifications'),(44,1,1659597034,1662083538,'注销账号','&lt;p style=&quot;white-space: normal; line-height: 1.5em;&quot;&gt;&lt;strong&gt;&amp;nbsp; &amp;nbsp; 注销账号是不可恢复的操作，你应自行备份账号相关的信息和数据，操作之前，请确认与账号相关的所有服务均已妥善处理。&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;white-space: normal; line-height: 1.5em;&quot;&gt;&lt;strong&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;注销账号后，你将无法再使用本账号或找回你添加的任何内容信息，包括但不限于：&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;white-space: normal; line-height: 1.5em;&quot;&gt;（1）你将无法登录、使用本账号，你的朋友将无法通过本账号联系你。&lt;/p&gt;&lt;p style=&quot;white-space: normal; line-height: 1.5em;&quot;&gt;（2）你账号的个人资料和历史信息（包含昵称、头像、作品、消息记录、粉丝、关注等）都将无法找回。&lt;/p&gt;&lt;p style=&quot;white-space: normal; line-height: 1.5em;&quot;&gt;（3）关注你账号的所有用户将被取消关注，与账号相关的所有功能或服务都将无法继续使用。&lt;/p&gt;',NULL,0,9999,'Logout'),(45,36315,1688535717,1702690878,'什么是基本功能模式？','&lt;p&gt;基本功能模式&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;color: rgb(51, 51, 51); font-family: -apple-system, system-ui, BlinkMacSystemFont, &amp;quot;Segoe UI&amp;quot;, Roboto, &amp;quot;Helvetica Neue&amp;quot;, Arial, &amp;quot;PingFang SC&amp;quot;, &amp;quot;Hiragino Sans GB&amp;quot;, &amp;quot;Microsoft YaHei&amp;quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);&quot;&gt;What is basic functional mode?&lt;/span&gt;&lt;/p&gt;',NULL,0,9999,'What is basic functional mode?'),(46,36315,1698268113,0,'充值送靓号','&lt;p&gt;&lt;img src=&quot;/upload/admin/20231026/5d1e710505f618ec0b74b45ae08bc414.jpg&quot; title=&quot;15235f153508417aacf545978832c3b.jpg&quot; alt=&quot;15235f153508417aacf545978832c3b.jpg&quot;/&gt;&lt;/p&gt;',NULL,0,9999,''),(47,36315,1698268302,0,'充值送靓号','&lt;p&gt;11111111111&lt;/p&gt;',NULL,0,9999,''),(48,1,1702023488,0,'打扫打扫','&lt;p&gt;是第三代&lt;/p&gt;',NULL,0,9999,'');
